let trBusy=false;
function trNode(n){const raw=n.__en!==undefined?n.__en:n.nodeValue;const k=raw.trim();if(!k)return;const d=LANG!=='en'&&DICT[LANG][k];if(d){if(n.__en===undefined)n.__en=raw;const v=raw.replace(k,d);if(n.nodeValue!==v)n.nodeValue=v}else if(n.__en!==undefined){n.nodeValue=n.__en;delete n.__en}}
function trAll(root){if(LANG==='en'&&!root.__tr)return;trBusy=true;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentNode&&/^(SCRIPT|STYLE|TEXTAREA)$/.test(n.parentNode.nodeName)?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});let n;while(n=w.nextNode())trNode(n);trBusy=false}
function setLang(l){LANG=l;localStorage.setItem('bn-lang',l);document.documentElement.lang=l;document.body.__tr=true;trAll(document.body)}
new MutationObserver(()=>{if(trBusy)return;clearTimeout(trAll.t);trAll.t=setTimeout(()=>{if(LANG!=='en')trAll(document.body)},60)}).observe(document.documentElement,{childList:true,subtree:true});
addEventListener('beforeinstallprompt',e=>{e.preventDefault();INST=e;document.querySelectorAll('[data-act=install]').forEach(b=>b.hidden=false)});
addEventListener('appinstalled',()=>{INST=null;document.querySelectorAll('[data-act=install]').forEach(b=>b.hidden=true)});
document.addEventListener('click',async e=>{const b=e.target.closest&&e.target.closest('[data-act]');if(!b)return;if(b.dataset.act==='theme'){THEME=THEME==='auto'?'dark':THEME==='dark'?'light':'auto';localStorage.setItem('bn-theme',THEME);applyTheme();document.querySelectorAll('[data-act=theme]').forEach(x=>x.textContent=themeLabel())}else if(b.dataset.act==='install'&&!INST&&IOS){toast('Tap the Share button, then Add to Home Screen.')}else if(b.dataset.act==='install'&&INST){INST.prompt();await INST.userChoice.catch(()=>0);INST=null;b.hidden=true}});
document.addEventListener('change',e=>{if(e.target.dataset&&e.target.dataset.act==='lang')setLang(e.target.value)});
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',applyTheme);
if(LANG!=='en'){document.documentElement.lang=LANG;document.body.__tr=true}

let toastT;function toast(m){const t=$('toast');t.textContent=m;t.classList.add('on');clearTimeout(toastT);toastT=setTimeout(()=>t.classList.remove('on'),3200)}
function modal(html){$('modal-content').innerHTML=html;if(!$('modal').open)$('modal').showModal()}function closeModal(){if($('modal').open)$('modal').close()}
$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closeModal()});
const digits=p=>String(p||'').replace(/\D/g,'');
function wa(phone,text){let d=digits(phone);if(d.length===10)d='91'+d;return `https://wa.me/${d}?text=${encodeURIComponent(text)}`}
const initials=n=>String(n||'?').trim().split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase();
function upiLink(c,amt,note){return `upi://pay?pa=${encodeURIComponent(c.upiId)}&pn=${encodeURIComponent(c.upiName||c.name)}&am=${amt}&cu=INR&tn=${encodeURIComponent(note)}`}
function qrSvg(text){try{const q=qrcode(0,'M');q.addData(text);q.make();return q.createSvgTag({cellSize:5,margin:2,scalable:true})}catch(e){return '<p class="hint">QR could not be made. Use the UPI id instead.</p>'}}
function code8(){const a='ABCDEFGHJKLMNPQRSTUVWXYZ23456789',b=crypto.getRandomValues(new Uint8Array(8));return [...b].map(x=>a[x%a.length]).join('')}
const gate=fn=>async e=>{const b=e.currentTarget;if(b.disabled)return;b.disabled=true;try{await fn(e)}catch(x){console.error(x);toast(friendly(x))}finally{b.disabled=false}};
function friendly(x){const c=x?.code||'';if(c.includes('permission-denied'))return 'Not allowed. Check you are signed in to the right account.';if(c.includes('unavailable')||c.includes('network'))return 'You look offline. Try again when connected.';if(c.includes('resource-exhausted'))return 'Daily free limit reached. Try again tomorrow.';return x?.message||'Something went wrong.'}
const authErr=c=>({'auth/invalid-credential':'Email or password is wrong.','auth/invalid-email':'Enter a valid email.','auth/email-already-in-use':'This email already has an account. Sign in instead.','auth/weak-password':'Use at least 8 characters.','auth/too-many-requests':'Too many tries. Wait a few minutes.','auth/network-request-failed':'No connection.'}[c]||'Could not sign in. Try again.');
