function legalLinks(){return `<footer class="legal"><a href="#/privacy">Privacy</a><a href="#/terms">Terms</a><a href="legacy-v2/">Classic notebook</a></footer><div class="prefs noprint"><button class="small" data-act="theme" aria-label="Change theme">${themeLabel()}</button><label class="sr" for="lang-s">Language</label><select id="lang-s" data-act="lang"><option value="en" ${LANG==='en'?'selected':''}>English</option><option value="hi" ${LANG==='hi'?'selected':''}>हिन्दी</option><option value="bn" ${LANG==='bn'?'selected':''}>বাংলা</option></select><button class="small" data-act="install" ${INST||IOS?'':'hidden'}>Install app</button></div>`}
function mount(html){S.view++;$('app').innerHTML=html;window.scrollTo(0,0);const h=document.querySelector('#app h1');document.title=(h&&h.textContent.trim()?h.textContent.trim()+' - ':'')+'BatchNotes';const m=$('app').querySelector('main,.main');if(m&&!m.hasAttribute('tabindex'))m.setAttribute('tabindex','-1');reveal()}
function reveal(){const els=document.querySelectorAll('#app .rv,#app .feat .card,#app .steps>div');if(!('IntersectionObserver' in window)||matchMedia('(prefers-reduced-motion:reduce)').matches)return;els.forEach((e,i)=>{e.classList.add('pre');e.style.transitionDelay=(i%4)*60+'ms'});const io=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.classList.remove('pre');io.unobserve(x.target)}}),{threshold:.12});els.forEach(e=>io.observe(e))}
