/* ---------- notes and PDFs (expire after 14 days) ---------- */
const TTL_DAYS=14,CHK=700000,MAXPDF=3*1024*1024;
const expDate=()=>new Date(Date.now()+TTL_DAYS*864e5-120000);
const fmtD=d=>d.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});
const expOf=n=>n.expireAt.toDate();
async function dropNote(ref,cnt){const b=writeBatch(db);if(cnt==null){const p=await getDocs(collection(ref,'pieces'));p.docs.forEach(x=>b.delete(x.ref))}else for(let i=0;i<cnt;i++)b.delete(doc(collection(ref,'pieces'),String(i).padStart(3,'0')));b.delete(ref);await b.commit()}
async function cleanupNotes(){const snap=await getDocs(query(col('notes'),where('expireAt','<=',Timestamp.now())));for(const d of snap.docs)await dropNote(d.ref);return snap.size}
async function notesView(){try{await cleanupNotes()}catch(x){console.error(x)}
const snap=await getDocs(col('notes'));const ns=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>b.created.localeCompare(a.created));
page('notes',`${head('Notes and PDFs','Students in the batch you pick can read these. Each item is deleted after 14 days.',`<button class="primary" id="n-new">${ico('plus')}New note</button><button id="n-pdf">${ico('download')}Upload PDF</button>`)}
${ns.length?`<div class="list">${ns.map(n=>`<div class="item"><div class="t"><b>${esc(n.title)}</b><span>${n.kind==='pdf'?'PDF':'Note'} - ${esc(n.batch==='all'?'All batches':n.batch)} - expires ${fmtD(expOf(n))}</span></div><button class="small" data-o="${n.id}">Open</button><button class="small danger" data-x="${n.id}" aria-label="Delete ${esc(n.title)}">${ico('trash')}</button></div>`).join('')}</div>`:empty('book','No notes yet')}
<p class="hint" style="margin-top:12px">Each item is hidden for students the moment it expires and is erased the next time you or a student in that batch opens the app.</p>`);
const bs=batches();const sel=`<label for="n-b">Who can read it</label><select id="n-b"><option value="all">All batches</option>${bs.map(b=>`<option>${esc(b)}</option>`).join('')}</select>`;
$('n-new').onclick=()=>{modal(`<h2>New note</h2><form id="nf"><label for="n-t">Title</label><input id="n-t" maxlength="80">${sel}<label for="n-x">Note</label><textarea id="n-x" rows="10" maxlength="20000" style="min-height:200px"></textarea><p class="hint">Plain text. Deleted on ${fmtD(expDate())}.</p><p class="err" id="n-e" role="alert"></p><div class="row"><button type="button" id="cc">Cancel</button><button class="primary">Publish</button></div></form>`);$('cc').onclick=closeModal;
$('nf').onsubmit=gate(async e=>{e.preventDefault();const title=$('n-t').value.trim(),body=$('n-x').value.trim();if(!title||!body){$('n-e').textContent='Add a title and some text.';return}await addDoc(col('notes'),{title,body,batch:$('n-b').value,kind:'note',created:new Date().toISOString(),expireAt:Timestamp.fromDate(expDate())});closeModal();toast('Published');route()})};
$('n-pdf').onclick=()=>{modal(`<h2>Upload a PDF</h2><form id="pf"><label for="p-t">Title</label><input id="p-t" maxlength="80">${sel}<label for="p-f">PDF file (up to 3 MB)</label><input id="p-f" type="file" accept="application/pdf"><p class="hint">Deleted on ${fmtD(expDate())}. Not end-to-end encrypted.</p><p class="err" id="n-e" role="alert"></p><div class="row"><button type="button" id="cc">Cancel</button><button class="primary">Upload</button></div></form>`);$('cc').onclick=closeModal;
$('pf').onsubmit=gate(async e=>{e.preventDefault();const f=$('p-f').files[0],title=$('p-t').value.trim()||(f?f.name.replace(/\.pdf$/i,''):'');const er=$('n-e');er.textContent='';if(!f){er.textContent='Choose a PDF.';return}if(f.type!=='application/pdf'&&!/\.pdf$/i.test(f.name)){er.textContent='That is not a PDF.';return}if(f.size>MAXPDF){er.textContent='That file is over 3 MB. Compress it first.';return}
const data=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]||'');r.onerror=no;r.readAsDataURL(f)});const parts=[];for(let i=0;i<data.length;i+=CHK)parts.push(data.slice(i,i+CHK));
const ex=Timestamp.fromDate(expDate()),ref=doc(col('notes')),b=writeBatch(db);b.set(ref,{title,batch:$('n-b').value,kind:'pdf',size:f.size,n:parts.length,created:new Date().toISOString(),expireAt:ex});parts.forEach((p,i)=>b.set(doc(collection(ref,'pieces'),String(i).padStart(3,'0')),{i,data:p,expireAt:ex}));await b.commit();closeModal();toast('Uploaded');route()})};
document.querySelectorAll('[data-o]').forEach(b=>b.onclick=gate(()=>openNote(S.user.uid,ns.find(n=>n.id===b.dataset.o))));
document.querySelectorAll('[data-x]').forEach(b=>b.onclick=gate(async()=>{if(!confirm('Delete this item for everyone?'))return;await dropNote(doc(col('notes'),b.dataset.x));toast('Deleted');route()}))}
async function openNote(cid,n){if(n.kind!=='pdf'){modal(`<h2>${esc(n.title)}</h2><p class="hint">Expires ${fmtD(expOf(n))}</p><div style="white-space:pre-wrap;line-height:1.6;max-height:60vh;overflow:auto">${esc(n.body)}</div><div class="row" style="margin-top:12px"><button id="cc">Close</button></div>`);$('cc').onclick=closeModal;return}
const ps=await getDocs(collection(db,'v3centres',cid,'notes',n.id,'pieces'));const bin=atob(ps.docs.map(d=>d.data()).sort((x,y)=>x.i-y.i).map(x=>x.data).join(''));const u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);const url=URL.createObjectURL(new Blob([u],{type:'application/pdf'}));
modal(`<h2>${esc(n.title)}</h2><p class="hint">PDF - expires ${fmtD(expOf(n))}</p><div class="row"><a class="button primary" href="${url}" target="_blank" rel="noopener">Open PDF</a><a class="button" href="${url}" download="${esc(n.title)}.pdf">Download</a><button id="cc">Close</button></div>`);$('cc').onclick=closeModal}
async function studentNotes(box,cid,batch){if(!box)return;const run=b=>getDocs(query(collection(db,'v3centres',cid,'notes'),where('batch','==',b)));
const rs=await Promise.all([run('all'),...(batch&&batch!=='all'?[run(batch)]:[])]);const all=rs.flatMap(r=>r.docs.map(d=>({ref:d.ref,id:d.id,...d.data()})));all.filter(n=>expOf(n)<=new Date()).forEach(n=>dropNote(n.ref,n.n||0).catch(()=>{}));const ns=all.filter(n=>expOf(n)>new Date()).sort((a,b)=>b.created.localeCompare(a.created));
box.innerHTML=ns.length?ns.map(n=>`<div class="item" style="padding-left:0;padding-right:0"><div class="t"><b>${esc(n.title)}</b><span>${n.kind==='pdf'?'PDF':'Note'} - expires ${fmtD(expOf(n))}</span></div><button class="small" data-n="${n.id}">Open</button></div>`).join(''):'<p class="muted">No notes right now.</p>';
box.querySelectorAll('[data-n]').forEach(b=>b.onclick=gate(()=>openNote(cid,ns.find(n=>n.id===b.dataset.n))))}
function batchDeleteModal(){const bs=batches();if(!bs.length){toast('No batches yet');return}modal(`<h2>Delete a batch</h2><p class="muted">This removes the students in the batch, their records, and the batch's notes and PDFs. It cannot be undone.</p><label for="bd-b">Batch</label><select id="bd-b">${bs.map(b=>`<option>${esc(b)}</option>`).join('')}</select><p class="hint" id="bd-n"></p><label for="bd-c">Type the batch name to confirm</label><input id="bd-c" autocomplete="off"><p class="err" id="bd-e" role="alert"></p><div class="row"><button type="button" id="cc">Cancel</button><button class="danger" id="bd-go">Delete batch</button></div>`);$('cc').onclick=closeModal;
const info=()=>{const b=$('bd-b').value;$('bd-n').textContent=S.students.filter(s=>s.batch===b).length+' students will be deleted.'};$('bd-b').onchange=info;info();
$('bd-go').onclick=gate(async()=>{const b=$('bd-b').value;if($('bd-c').value.trim()!==b){$('bd-e').textContent='The name does not match.';return}
for(const s of S.students.filter(x=>x.batch===b))await deleteStudent(s);
for(const n of ['notes','tests','homework','members','exams']){const r=await getDocs(query(col(n),where('batch','==',b)));for(const d of r.docs){if(n==='notes')await dropNote(d.ref);else if(n==='exams'){const wb=writeBatch(db);for(const k of ['subs','starts','paper','key'])(await getDocs(collection(d.ref,k))).docs.forEach(x=>wb.delete(x.ref));wb.delete(d.ref);await wb.commit()}else await deleteDoc(d.ref)}}
const cs=(S.centre.batches||[]).filter(x=>x!==b);if(cs.length!==(S.centre.batches||[]).length){await updateDoc(C(),{batches:cs,ownerUid:S.user.uid});S.centre.batches=cs}
closeModal();toast('Batch deleted');route()})}

/* ---------- online exams ---------- */
function parseQs(txt){const blocks=txt.replace(/\r/g,'').split(/\n\s*\n/).map(b=>b.split('\n').map(x=>x.trim()).filter(Boolean)).filter(b=>b.length);const qs=[],ans=[];blocks.forEach((b,i)=>{const q=b[0].replace(/^\d+[.)]\s*/,'');const raw=b.slice(1);if(raw.length<2||raw.length>5)throw Error('Question '+(i+1)+' needs 2 to 5 options, one per line.');const k=raw.map((x,j)=>x.startsWith('*')?j:-1).filter(j=>j>=0);if(k.length!==1)throw Error('Question '+(i+1)+': put * at the start of exactly one correct option.');qs.push({q:q.slice(0,400),o:raw.map(x=>x.replace(/^\*\s*/,'').slice(0,200))});ans.push(k[0])});if(!qs.length)throw Error('Add at least one question.');if(qs.length>50)throw Error('Up to 50 questions per exam.');return {qs,ans}}
async function examsView(){const snap=await getDocs(col('exams'));const ex=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>b.created.localeCompare(a.created));
page('exams',`${head('Online exams','Multiple choice and timed. Students take them on their phone and you get marks and ranks.',`<button class="primary" id="ex-new">${ico('plus')}New exam</button>`)}${ex.length?`<div class="list">${ex.map(e=>`<div class="item"><div class="t"><b>${esc(e.title)}</b><span>${esc(e.batch==='all'?'All batches':e.batch)} - ${e.n} questions - ${e.mins} min - ${e.open?'Open':'Closed'}</span></div><button class="small primary" data-e="${e.id}">Open</button></div>`).join('')}</div>`:empty('check','No exams yet','Create one, pick a batch, and students can start it right away.')}`);
$('ex-new').onclick=()=>{const bs=batches();modal(`<h2>New exam</h2><form id="xf"><label for="x-t">Title</label><input id="x-t" maxlength="80" placeholder="Chapter 3 quiz"><div class="grid2"><div><label for="x-b">Batch</label><select id="x-b"><option value="all">All batches</option>${bs.map(b=>`<option>${esc(b)}</option>`).join('')}</select></div><div><label for="x-m">Minutes</label><input id="x-m" inputmode="numeric" value="20"></div></div><label for="x-q">Questions</label><textarea id="x-q" rows="12" style="min-height:230px" placeholder="What is 2 + 2?&#10;3&#10;*4&#10;5&#10;&#10;Capital of India?&#10;*New Delhi&#10;Mumbai"></textarea><label for="x-f" class="hint" style="margin-top:6px">Or load the questions from a .txt file</label><input type="file" id="x-f" accept=".txt,text/plain"><p class="hint">One question per block, blank line between blocks. First line is the question, then one option per line. Put * before the correct option. 1 mark each.</p><p class="err" id="x-e" role="alert"></p><div class="row"><button type="button" id="cc">Cancel</button><button class="primary">Publish exam</button></div></form>`);$('cc').onclick=closeModal;$('x-f').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>200000){toast('That file is too large');return}$('x-q').value=(await f.text()).replace(/\r/g,'');toast('Questions loaded. Check them, then publish.')};
$('xf').onsubmit=gate(async e=>{e.preventDefault();const title=$('x-t').value.trim(),mins=Math.round(num($('x-m').value));const er=$('x-e');er.textContent='';if(!title){er.textContent='Add a title.';return}if(!(mins>=1&&mins<=180)){er.textContent='Minutes must be 1 to 180.';return}let p;try{p=parseQs($('x-q').value)}catch(x){er.textContent=x.message;return}
const ref=doc(col('exams')),b=writeBatch(db);b.set(ref,{title,batch:$('x-b').value,mins,n:p.qs.length,max:p.qs.length,open:true,created:new Date().toISOString()});b.set(doc(collection(ref,'paper'),'q'),{qs:p.qs});b.set(doc(collection(ref,'key'),'k'),{ans:p.ans});await b.commit();closeModal();toast('Exam published');route()})};
document.querySelectorAll('[data-e]').forEach(b=>b.onclick=gate(()=>examDetail(ex.find(x=>x.id===b.dataset.e))))}
async function examDetail(e){const er=doc(col('exams'),e.id);const [ss,kd]=await Promise.all([getDocs(collection(er,'subs')),getDoc(doc(collection(er,'key'),'k'))]);const ans=kd.data().ans;
const rows=ss.docs.map(d=>({uid:d.id,...d.data()})).map(s=>({...s,score:(s.a||[]).reduce((t,x,i)=>t+(x===ans[i]?1:0),0)})).sort((a,b)=>b.score-a.score);
page('exams',`${head(esc(e.title),esc(e.batch==='all'?'All batches':e.batch)+' - '+e.n+' questions - '+e.mins+' min',`<button class="small" id="bk">${ico('back')}All exams</button>`)}
<div class="card"><div class="row between"><b>${rows.length} submitted</b><span class="hint">${e.open?'Open for students':'Closed'}</span></div>${rows.length?`<div class="list" style="margin-top:8px">${rows.map(s=>`<div class="item"><div class="t"><b>${esc(s.name)}</b><span>${s.score}/${e.n}${s.left?' - left the page '+s.left+(s.left>1?' times':' time'):''}</span></div></div>`).join('')}</div>`:'<p class="muted" style="margin-top:8px">No submissions yet.</p>'}</div>
<div class="row" style="margin-top:12px"><button class="primary" id="x-pub" ${rows.length?'':'disabled'}>Save to results and ranks</button><button id="x-tog">${e.open?'Close exam':'Reopen exam'}</button><button class="danger" id="x-del">Delete</button></div>
<p class="hint" style="margin-top:8px">Marks are worked out from the submitted answers when you open this page. Times are enforced by the database. "Left the page" is reported by the student's phone and can be faked, so use it as a hint only.</p>`);
$('bk').onclick=()=>{location.hash='#/exams';route()};
$('x-tog').onclick=gate(async()=>{await updateDoc(er,{open:!e.open});toast(e.open?'Closed':'Reopened');location.hash='#/exams';route()});
$('x-pub').onclick=gate(async()=>{const tot=rows.length,avg=Math.round(rows.reduce((a,x)=>a+x.score,0)/tot*10)/10;const date=ymd(new Date());const b=writeBatch(db);b.set(doc(col('tests'),e.id),{name:e.title,batch:e.batch==='all'?'':e.batch,max:e.n,date,count:tot,exam:true});rows.forEach(s=>{const rank=1+rows.filter(y=>y.score>s.score).length;b.set(doc(col('results'),e.id+'_'+s.sid),{sid:s.sid,tid:e.id,name:e.title,date,batch:e.batch==='all'?'':e.batch,score:s.score,max:e.n,rank,total:tot,avg})});await b.commit();toast('Saved. Students can see their marks and rank.')});
$('x-del').onclick=gate(async()=>{if(!confirm('Delete this exam and all its answers?'))return;const b=writeBatch(db);for(const n of ['subs','starts','paper','key']){(await getDocs(collection(er,n))).docs.forEach(d=>b.delete(d.ref))}b.delete(er);await b.commit();toast('Deleted');location.hash='#/exams';route()})}
async function studentExams(box,cid,batch,sid,name){if(!box)return;const run=b=>getDocs(query(collection(db,'v3centres',cid,'exams'),where('batch','==',b)));
const rs=await Promise.all([run('all'),...(batch&&batch!=='all'?[run(batch)]:[])]);const ex=rs.flatMap(r=>r.docs.map(d=>({id:d.id,...d.data()}))).filter(e=>e.open).sort((a,b)=>b.created.localeCompare(a.created));
const st=await Promise.all(ex.map(async e=>{const er=doc(db,'v3centres',cid,'exams',e.id);const [sub,start]=await Promise.all([getDoc(doc(er,'subs',S.user.uid)),getDoc(doc(er,'starts',S.user.uid))]);return {sub:sub.exists(),started:start.exists()}}));
box.innerHTML=ex.length?ex.map((e,i)=>`<div class="item" style="padding-left:0;padding-right:0"><div class="t"><b>${esc(e.title)}</b><span>${e.n} questions - ${e.mins} min${st[i].sub?' - submitted':st[i].started?' - in progress':''}</span></div>${st[i].sub?'<span class="hint">Done</span>':`<button class="small primary" data-x="${e.id}">${st[i].started?'Continue':'Start'}</button>`}</div>`).join(''):'<p class="muted">No exams open right now.</p>';
box.querySelectorAll('[data-x]').forEach(b=>b.onclick=gate(()=>takeExam(cid,ex.find(e=>e.id===b.dataset.x),sid,name)))}
async function takeExam(cid,e,sid,name){const er=doc(db,'v3centres',cid,'exams',e.id);const sr=doc(er,'starts',S.user.uid);let st=await getDoc(sr);
if(!st.exists()){if(!confirm('Start "'+e.title+'"? You have '+e.mins+' minutes and one attempt. The timer cannot be paused.'))return;await setDoc(sr,{t:serverTimestamp()});st=await getDoc(sr)}
const t0=st.data().t.toMillis(),end=t0+e.mins*60000;const qs=(await getDoc(doc(er,'paper','q'))).data().qs;let left=0,done=false;const onv=()=>{if(document.hidden)left++};document.addEventListener('visibilitychange',onv);
mount(pshell(`<h1>${esc(e.title)}</h1><div class="card" style="position:sticky;top:8px;z-index:5;display:flex;justify-content:space-between;align-items:center"><b id="tm">--:--</b><span class="hint">Answer all, then submit. One attempt.</span></div>
<form id="xq" class="stack" style="margin-top:12px">${qs.map((q,i)=>`<fieldset class="card" style="margin:0"><legend style="padding:0 6px;font-weight:600">${i+1}. ${esc(q.q)}</legend>${q.o.map((o,j)=>`<label class="inline" style="padding:6px 0"><input type="radio" name="q${i}" value="${j}">${esc(o)}</label>`).join('')}</fieldset>`).join('')}<p class="err" id="xe" role="alert"></p><button class="primary" id="xs" style="width:100%">Submit answers</button></form>`));
const fin=gate(async()=>{if(done)return;const a=qs.map((_,i)=>{const r=document.querySelector(`input[name=q${i}]:checked`);return r?+r.value:-1});if(!a.includes(-1)||Date.now()>=end||confirm('Some questions are unanswered. Submit anyway?')){done=true;clearInterval(iv);document.removeEventListener('visibilitychange',onv);try{await setDoc(doc(er,'subs',S.user.uid),{a,sid,name,left,t:serverTimestamp()})}catch(x){mount(pshell(`<h1>Not submitted</h1><div class="card"><p>${x.code?.includes('permission')?'The time limit was over or you already submitted, so the database refused it.':esc(friendly(x))}</p><button class="primary" id="bk">Back</button></div>`));$('bk').onclick=()=>parentHome();return}
const key=(await getDoc(doc(er,'key','k'))).data().ans;const sc=a.reduce((t,x,i)=>t+(x===key[i]?1:0),0);mount(pshell(`<h1>Submitted</h1><div class="card stat"><b>${sc}/${e.n}</b><span>Your marks. The teacher will confirm them and add your rank.</span></div><p style="margin-top:12px"><button class="primary" id="bk">Back to home</button></p>`));$('bk').onclick=()=>parentHome()}});
$('xs').onclick=e2=>{e2.preventDefault();fin(e2)};const tick=()=>{const r=Math.max(0,end-Date.now());const m=Math.floor(r/60000),s=Math.floor(r%60000/1000);const t=$('tm');if(t){t.textContent=String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');t.style.color=r<60000?'var(--red)':'inherit'}if(r<=0&&!done){done=true;clearInterval(iv);const f=$('xs');if(f){done=false;fin({currentTarget:f})}}};const iv=setInterval(tick,500);tick()}
/* ---------- student's own notes (private, saved in their account) ---------- */
async function myNotes(box){const sn=await getDocs(collection(db,'v3users',S.user.uid,'mynotes'));const ns=sn.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>b.updated.localeCompare(a.updated));
box.innerHTML=`<div class="row between"><h3 style="margin:0">My notes</h3><button class="small primary" id="mn-new">${ico('plus')}New note</button></div><p class="hint" style="margin:4px 0 8px">Private to you unless you tick Share with my teacher on a note. Saved in your account, so they stay on any phone you sign in on.</p>${ns.length?ns.map(n=>`<div class="item" style="padding-left:0;padding-right:0"><div class="t"><b>${esc(n.title)}</b><span>${esc(new Date(n.updated).toLocaleDateString('en-IN',{day:'numeric',month:'short'}))}${n.shared?' - shared with teacher':''}</span></div><button class="small" data-mn="${n.id}">Open</button></div>`).join(''):'<p class="muted">Nothing yet. Tap New note.</p>'}`;
const edit=n=>{modal(`<h2>${n?'Edit note':'New note'}</h2><form id="mf"><label for="m-t">Title</label><input id="m-t" maxlength="80" value="${esc(n?.title||'')}"><label for="m-x">Note</label><textarea id="m-x" rows="12" maxlength="20000" style="min-height:240px">${esc(n?.body||'')}</textarea>${S.shareCid?`<label class="inline" style="padding:8px 0"><input type="checkbox" id="m-sh" ${n?.shared?'checked':''}> Share this note with my teacher. Off means only you can read it.</label>`:''}<p class="err" id="m-e" role="alert"></p><div class="row"><button type="button" id="cc">Cancel</button><button class="primary">Save to my account</button></div></form>`);$('cc').onclick=closeModal;
$('mf').onsubmit=gate(async e=>{e.preventDefault();const title=$('m-t').value.trim(),body=$('m-x').value;if(!title){$('m-e').textContent='Add a title.';return}if(!n&&ns.length>=100){$('m-e').textContent='You can keep up to 100 notes.';return}const sh=!!($('m-sh')&&$('m-sh').checked);const d={title,body,updated:new Date().toISOString(),shared:sh};let nid;if(n){nid=n.id;await setDoc(doc(db,'v3users',S.user.uid,'mynotes',n.id),d)}else{nid=(await addDoc(collection(db,'v3users',S.user.uid,'mynotes'),d)).id}if(S.shareCid){const sr=doc(db,'v3centres',S.shareCid,'shared',S.user.uid+'_'+nid);try{if(sh)await setDoc(sr,{uid:S.user.uid,nid,name:S.profile.name,title,body,updated:d.updated});else if(n&&n.shared)await deleteDoc(sr)}catch(x){console.error(x);toast('Saved, but sharing failed. Try again.')}}closeModal();toast('Saved');myNotes(box)})};
const nn=box.querySelector('#mn-new');if(!nn||!box.isConnected)return;nn.onclick=()=>edit(null);
box.querySelectorAll('[data-mn]').forEach(b=>b.onclick=()=>{const n=ns.find(x=>x.id===b.dataset.mn);modal(`<h2>${esc(n.title)}</h2><div style="white-space:pre-wrap;line-height:1.6;max-height:55vh;overflow:auto">${esc(n.body)}</div><div class="row" style="margin-top:12px"><button class="primary" id="mn-e">Edit</button><button id="mn-d">${ico('download')}Download</button><button class="danger" id="mn-x">Delete</button><button id="cc">Close</button></div>`);$('cc').onclick=closeModal;$('mn-e').onclick=()=>edit(n);
$('mn-d').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([n.title+'\n\n'+n.body],{type:'text/plain'}));a.download=n.title.replace(/[^\w -]+/g,'').trim()+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)};
$('mn-x').onclick=gate(async()=>{if(!confirm('Delete this note?'))return;await deleteDoc(doc(db,'v3users',S.user.uid,'mynotes',n.id));if(S.shareCid&&n.shared){try{await deleteDoc(doc(db,'v3centres',S.shareCid,'shared',S.user.uid+'_'+n.id))}catch(x){console.error(x)}}closeModal();toast('Deleted');myNotes(box)})})}
/* ---------- student ---------- */
function pshell(inner){return `<div class="narrow" style="max-width:640px"><div class="row between" style="margin-bottom:14px"><a class="brand" href="#/p"><img src="logo.svg" alt="">BatchNotes</a><button class="small" id="out">${ico('out')}Sign out</button></div>${inner}${legalLinks()}</div>`}
async function parentHome(){const lk=await getDocs(collection(db,'v3users',S.user.uid,'links'));const links=lk.docs.map(d=>({id:d.id,...d.data()}));S.shareCid=links[0]&&links[0].cid||null;
const redeem=`<form class="card" id="rf"><h3>Join your teacher's batch</h3><p class="muted">Enter the 8-letter code your teacher sent you.</p><label for="r-c">Code</label><input id="r-c" maxlength="8" autocapitalize="characters" autocomplete="off" style="text-transform:uppercase;letter-spacing:.15em;font-weight:600"><label for="r-n">Your name</label><input id="r-n" maxlength="60" value="${esc(S.profile.name)}"><p class="err" id="r-e" role="alert"></p><button class="primary" id="r-go">Send request</button></form>`;
mount(pshell(`<h1>Hello, ${esc(S.profile.name.split(' ')[0])}</h1>${links.length?'':'<p class="muted">Enter the code from your teacher to see attendance, fees and results.</p>'}<div id="kids" class="stack"></div><div class="card" id="mynotes" style="margin-top:12px"></div><div style="margin-top:14px">${redeem}</div>`));myNotes($('mynotes')).catch(x=>{console.error(x);$('mynotes').innerHTML='<p class="muted">Could not load your notes.</p>'});$('out').onclick=()=>signOut(auth);
$('rf').onsubmit=gate(async e=>{e.preventDefault();const c=$('r-c').value.trim().toUpperCase(),nm=$('r-n').value.trim();const er=$('r-e');er.textContent='';if(c.length!==8||!nm){er.textContent='Enter the 8-letter code and your name.';return}
let cd;try{cd=await getDoc(doc(db,'v3codes',c))}catch(x){cd=null}if(!cd||!cd.exists()){er.textContent='That code was not found. Check it with the teacher.';return}const {cid,sid}=cd.data();
try{await setDoc(doc(db,'v3centres',cid,'parents',S.user.uid+'_'+sid),{sid,code:c,name:nm,status:'pending'})}catch(x){er.textContent=x.code?.includes('permission')?'You are already linked to this centre, or the request was refused.':friendly(x);return}
await setDoc(doc(db,'v3users',S.user.uid,'links',cid+'_'+sid),{cid,sid});toast('Request sent. The teacher will approve it.');route()});
const box=$('kids');for(const l of links){const el=document.createElement('div');box.appendChild(el);childCard(el,l).catch(x=>{console.error(x);el.innerHTML=`<div class="card"><b>Could not load</b><p class="muted">${esc(friendly(x))}</p></div>`})}}
async function childCard(el,l){const pd=await getDoc(doc(db,'v3centres',l.cid,'parents',S.user.uid+'_'+l.sid));if(!pd.exists()||pd.data().status!=='approved'){el.innerHTML=`<div class="card"><b>${pd.exists()&&pd.data().status==='revoked'?'Request declined':'Waiting for the teacher'}</b><p class="muted">${pd.exists()&&pd.data().status==='revoked'?'Ask the teacher for a new code.':'The teacher has to approve your request before you can see anything.'}</p></div>`;return}
const cr=(n)=>collection(db,'v3centres',l.cid,n),q=n=>getDocs(query(cr(n),where('sid','==',l.sid)));
const [cd,sd,att,fees,res,hw]=await Promise.all([getDoc(doc(db,'v3centres',l.cid)),getDoc(doc(db,'v3centres',l.cid,'students',l.sid)),q('att'),q('fees'),q('results'),q('hw')]);const c=cd.data(),s=sd.data();
const m=mk(new Date()),a=att.docs.map(d=>d.data()).find(x=>x.month===m);const days=a?.days||{};const vals=Object.values(days);const pct=vals.length?Math.round(vals.filter(x=>x!=='A').length/vals.length*100):null;
const fl=fees.docs.map(d=>({id:d.id,...d.data()})).sort((x,y)=>y.month.localeCompare(x.month));const owe=fl.filter(f=>f.amount>(f.paid||0));const total=owe.reduce((t,f)=>t+f.amount-(f.paid||0),0);
const rl=res.docs.map(d=>d.data()).sort((x,y)=>y.date.localeCompare(x.date));const hl=hw.docs.map(d=>d.data()).sort((x,y)=>(y.created||'').localeCompare(x.created||'')).slice(0,6);
const dim=new Date(+m.slice(0,4),+m.slice(4),0).getDate(),first=(new Date(+m.slice(0,4),+m.slice(4)-1,1).getDay()+6)%7;
let cal=['M','T','W','T','F','S','S'].map(x=>`<div class="h">${x}</div>`).join('')+'<div style="background:none"></div>'.repeat(first);for(let i=1;i<=dim;i++){const v=days[String(i).padStart(2,'0')];cal+=`<div class="${v||''}" ${v?`aria-label="${i}: ${{P:'present',A:'absent',L:'late'}[v]}"`:''}>${i}</div>`}
el.innerHTML=`<div class="card"><div class="row"><div class="avatar">${esc(initials(s.name))}</div><div class="t"><h2 style="margin:0">${esc(s.name)}</h2><span class="muted">${esc(s.batch||'')} - ${esc(c.name)}</span></div></div></div>
<div class="grid"><div class="card stat"><b style="color:${pct!==null&&pct<75?'var(--red)':'inherit'}">${pct===null?'-':pct+'%'}</b><span>Attendance in ${MN[+m.slice(4)-1]}</span></div><div class="card stat"><b style="color:${total?'var(--red)':'var(--green)'}">${total?inr(total):'All paid'}</b><span>${total?'Fees due':'No fees due'}</span></div></div>
${total&&c.upiId?`<div class="card"><h3>Pay fees by UPI</h3>${owe.map(f=>`<div class="item" style="padding-left:0;padding-right:0"><div class="t"><b>${mlabel(f.month)} - ${inr(f.amount-(f.paid||0))}</b><span>${f.claim?'You told the teacher you paid':'Due'}</span></div><button class="small primary" data-pay="${f.id}">Pay</button></div>`).join('')}<p class="hint">Opens your UPI app. Money goes straight to ${esc(c.upiName||c.name)}. After paying, tap "I have paid" so the teacher can check.</p></div>`:total?`<div class="card"><b>Fees due ${inr(total)}</b><p class="muted">Ask the teacher how to pay.</p></div>`:''}
<div class="card"><h3>${MN[+m.slice(4)-1]} attendance</h3>${vals.length?`<div class="cal">${cal}</div><p class="hint" style="margin-top:8px">Green present, red absent, amber late.</p>`:'<p class="muted">Nothing recorded yet.</p>'}</div>
<div class="card"><h3>Homework</h3>${hl.length?hl.map(h=>`<div class="item" style="padding-left:0"><div class="t"><b>${esc(h.title)}</b><span>${h.due?'Due '+esc(h.due):''} ${esc(h.text||'')}</span></div></div>`).join(''):'<p class="muted">No homework posted.</p>'}</div>
<div class="card"><h3>Test results</h3>${rl.length?`<div style="overflow-x:auto"><table><thead><tr><th>Test</th><th>Marks</th><th>Rank</th></tr></thead><tbody>${rl.map(r=>`<tr><td>${esc(r.name)}<br><span class="hint">${esc(r.date)}</span></td><td>${r.score}/${r.max}</td><td>${r.rank}/${r.total}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No results yet.</p>'}</div>
<div class="card"><h3>Fee receipts</h3>${fl.some(f=>(f.payments||[]).length)?fl.flatMap(f=>(f.payments||[]).map(p=>`<div class="item" style="padding-left:0"><div class="t"><b>${mlabel(f.month)} - ${inr(p.amt)}</b><span>${esc(p.on)} - ${esc(p.mode)}</span></div></div>`)).join(''):'<p class="muted">No payments recorded yet.</p>'}</div>
<div class="card"><h3>Exams</h3><div id="ex-${l.sid}"><p class="muted">Loading...</p></div></div>
<div class="card"><h3>Notes and PDFs</h3><div id="nt-${l.sid}"><p class="muted">Loading...</p></div><p class="hint">Notes disappear 14 days after the teacher posts them.</p></div>
<div class="row"><a class="button" target="_blank" rel="noopener" href="${wa(c.phone,'Hi, this is '+s.name)}" ${c.phone?'':'hidden'}>${ico('wa')}Message the teacher</a></div>`;
studentExams(el.querySelector('#ex-'+l.sid),l.cid,s.batch,l.sid,S.profile.name).catch(x=>{console.error(x);const nb=el.querySelector('#ex-'+l.sid);if(nb)nb.innerHTML='<p class="muted">Could not load exams.</p>'});
studentNotes(el.querySelector('#nt-'+l.sid),l.cid,s.batch).catch(x=>{console.error(x);const nb=el.querySelector('#nt-'+l.sid);if(nb)nb.innerHTML='<p class="muted">Could not load notes.</p>'});
el.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>{const f=fl.find(x=>x.id===b.dataset.pay),amt=f.amount-(f.paid||0),link=upiLink(c,amt,s.name+' fee '+mlabel(f.month));
modal(`<h2>Pay ${inr(amt)}</h2><p class="muted">${mlabel(f.month)} fee for ${esc(s.name)} to ${esc(c.upiName||c.name)}</p><a class="button primary" style="width:100%" href="${esc(link)}">${ico('phone')}Open UPI app</a><p class="hint" style="text-align:center;margin:10px 0 0">On a computer? Scan this with your phone.</p><div class="qr">${qrSvg(link)}</div><p class="hint" style="text-align:center">UPI id: <b>${esc(c.upiId)}</b></p><label for="pc-n">Note for teacher (optional, like the UPI reference)</label><input id="pc-n" maxlength="60"><div class="row" style="margin-top:12px"><button id="cc">Close</button><button id="pc" class="primary">I have paid</button></div>`);$('cc').onclick=closeModal;
$('pc').onclick=gate(async()=>{await updateDoc(doc(db,'v3centres',l.cid,'fees',f.id),{claim:{on:ymd(new Date()),note:$('pc-n').value.trim()}});closeModal();toast('Teacher will check and confirm');parentHome()})})}
/* ---------- legal ---------- */
function legal(w){const P=w==='privacy';const body=P?`<h2>What we keep</h2><p>For each centre: the teacher's name and email, the centre name, phone and UPI id. For each student: name, batch, fee, and a contact name and WhatsApp number (the student's or a guardian's). Attendance days, fee records, test marks, homework and enquiries are stored too. Students give their own name and email when they create an account.</p><h2>Children's data</h2><p>Students are often minors. The teacher decides to add a student and is responsible for having consent from the student or, for minors, a guardian. Only collect what you need. We do not collect photos, addresses, school records or ID numbers, so please do not type them into name or note fields.</p><h2>Who can see it</h2><p>The teacher sees the whole centre. An approved student sees only their own records. Other teachers, other students and other centres cannot read it. Access is enforced by database rules and each student link needs teacher approval. A teacher can revoke a student's access or delete a student, which removes that student's attendance, fees, results and links.</p><h2>What is not private</h2><p>Classroom records are protected by account rules, but they are not end-to-end encrypted like notes and PDFs. The hosting provider (Google Firebase) can technically access stored data. The centre name, phone and UPI id are visible to anyone who has a valid invite code. Reminder text you send through WhatsApp is handled by WhatsApp under its own terms.</p><h2>Exams and your own notes</h2><p>Teachers can set timed multiple-choice exams. A student's answers and marks are visible to that student and the teacher only. Students can also keep private notes that only they can read, stored in their own account until they delete them.</p><h2>Notes and PDFs</h2><p>Notes and PDFs a teacher posts here are visible only to approved students of the batch the teacher picks. Each one is deleted automatically 14 days after it is posted: hidden at once, and erased the next time the teacher or a student of that batch opens the app after that. Teachers can delete an item, or a whole batch, earlier. They are not end-to-end encrypted.</p><h2>Money</h2><p>We do not process or hold payments and there is no payment gateway. UPI links open the student's own UPI app and pay the teacher directly. "I have paid" only tells the teacher to check. The teacher marks a fee as paid.</p><h2>Your choices</h2><p>Download students and fees as CSV in Settings. Delete a student in Students. To remove a whole centre or account, write to the developer through the contact on the BatchNotes page and it will be removed.</p><h2>No tracking</h2><p>No ads, no analytics scripts and no selling of data. The app loads fonts and a QR library from public CDNs.</p>`:`<h2>Using BatchNotes Classroom</h2><p>This is a free tool for teachers, offered as is, with no promise it is always available. Free hosting has daily limits; very heavy use can pause the service until the next day.</p><h2>Your duties as a teacher</h2><p>You are responsible for the accuracy of the records you enter, for having permission, from a guardian for minors, to store the student's details, and for the messages you send. You must not use it to harass, shame or publicly expose students or their families, and must not post anything unlawful.</p><h2>Payments</h2><p>BatchNotes is not a bank or payment service. Fees are paid directly between student and teacher. We are not responsible for payment disputes, wrong UPI ids or failed transfers. Always check your own UPI app before marking a fee paid.</p><h2>Students</h2><p>You can see only your own records. Do not share your login. Teachers can end your access at any time.</p><h2>Limits</h2><p>We try to keep data safe but cannot guarantee it. Keep your own backup using the CSV download. We may change or end the service. These notes are plain-language terms, not legal advice.</p>`;
const back=S.user?(S.profile?.role==='parent'?'#/p':'#/dash'):'#/';mount(`<div class="narrow" style="max-width:720px"><a class="muted row" href="${back}">${ico('back')}Back</a><h1 style="margin-top:14px">${P?'Privacy and safety':'Terms of use'}</h1><p class="hint">Last updated 22 October 2026</p>${body}${legalLinks()}</div>`)}

/* ---------- connection and error notices ---------- */
(()=>{const bar=document.createElement('div');bar.id='offbar';bar.setAttribute('role','status');bar.textContent='You are offline. Changes will not save until you reconnect.';document.body.appendChild(bar);const upd=()=>bar.classList.toggle('on',!navigator.onLine);addEventListener('online',()=>{upd();toast('Back online')});addEventListener('offline',upd);upd();
addEventListener('unhandledrejection',e=>{const c=e.reason&&e.reason.code||'';if(!navigator.onLine||/unavailable|network|deadline/.test(c)){toast('No internet right now. Try again when you are connected.')}})})();

async function sharedView(){const sn=await getDocs(col('shared'));const ns=sn.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>b.updated.localeCompare(a.updated));
page('shared',`${head('Notes shared by students','Students choose which notes to share with you. You can only read them.')}${ns.length?`<div class="list">${ns.map(n=>`<div class="item"><div class="t"><b>${esc(n.title)}</b><span>${esc(n.name)} - ${esc(new Date(n.updated).toLocaleDateString('en-IN',{day:'numeric',month:'short'}))}</span></div><button class="small" data-o="${n.id}">Read</button></div>`).join('')}</div>`:empty('book','Nothing shared yet','When a student ticks Share with my teacher on a note, it shows up here.')}`);
document.querySelectorAll('[data-o]').forEach(b=>b.onclick=()=>{const n=ns.find(x=>x.id===b.dataset.o);modal(`<h2>${esc(n.title)}</h2><p class="hint">By ${esc(n.name)}</p><div style="white-space:pre-wrap;line-height:1.6;max-height:55vh;overflow:auto">${esc(n.body)}</div><div class="row" style="margin-top:12px"><button class="primary" id="cc">Close</button></div>`);$('cc').onclick=closeModal})}
